#include <bits/stdc++.h>
using namespace std;

int main() {
    string text((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    if (!text.empty() && text.back() == '\n') text.pop_back();
    size_t cut = text.find('\n');
    int k = stoi(text.substr(0, cut));
    string message = text.substr(cut + 1);
    if ((int)message.size() <= k) {
        cout << message << "\n";
        return 0;
    }
    // keep whole prefix words while prefix + " ..." fits in k
    string chosen;
    size_t start = 0;
    while (start <= message.size()) {
        size_t end = message.find(' ', start);
        if (end == string::npos) end = message.size();
        string word = message.substr(start, end - start);
        size_t candidate = chosen.size() + word.size() + (chosen.empty() ? 0 : 1);
        if ((int)candidate + 4 > k) break;
        if (!chosen.empty()) chosen += ' ';
        chosen += word;
        start = end + 1;
    }
    cout << (chosen.empty() ? string("...") : chosen + " ...") << "\n";
}

import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws IOException {
        String text = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        if (text.endsWith("\n")) text = text.substring(0, text.length() - 1);
        int cut = text.indexOf('\n');
        int k = Integer.parseInt(text.substring(0, cut).trim());
        String message = text.substring(cut + 1);
        if (message.length() <= k) {
            System.out.println(message);
            return;
        }
        // keep whole prefix words while prefix + " ..." fits in k
        StringBuilder chosen = new StringBuilder();
        for (String word : message.split(" ", -1)) {
            int candidate = chosen.length() + word.length() + (chosen.length() > 0 ? 1 : 0);
            if (candidate + 4 > k) break;
            if (chosen.length() > 0) chosen.append(' ');
            chosen.append(word);
        }
        System.out.println(chosen.length() > 0 ? chosen + " ..." : "...");
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	text := strings.TrimSuffix(string(raw), "\n")
	first, message, _ := strings.Cut(text, "\n")
	k, _ := strconv.Atoi(strings.TrimSpace(first))
	if len(message) <= k {
		fmt.Println(message)
		return
	}
	// keep whole prefix words while prefix + " ..." fits in k
	chosen := []string{}
	length := 0
	for _, word := range strings.Split(message, " ") {
		candidate := length + len(word)
		if len(chosen) > 0 {
			candidate++
		}
		if candidate+4 > k {
			break
		}
		chosen = append(chosen, word)
		length = candidate
	}
	if len(chosen) == 0 {
		fmt.Println("...")
	} else {
		fmt.Println(strings.Join(chosen, " ") + " ...")
	}
}
